/**
 * Expose only fixed owner-workspace operations, without paths, Node access or arbitrary IPC.
 * Symbol index (generated by tools/update-symbol-index.ts):
 * @@SYMBOL_INDEX_START
 * - no top-level symbols
 * @@SYMBOL_INDEX_END
 */
"use strict";
const { contextBridge, ipcRenderer } = require("electron");
contextBridge.exposeInMainWorld("portalWorkspace", {
  load: () => ipcRenderer.invoke("portal:load"),
  save: (base, catalog, imported) => ipcRenderer.invoke("portal:save", base, catalog, imported),
  restore: (base, revision) => ipcRenderer.invoke("portal:restore", base, revision),
  importCatalog: () => ipcRenderer.invoke("portal:import"),
  exportCatalog: (kind) => ipcRenderer.invoke("portal:export", kind),
  quit: (dirty) => ipcRenderer.invoke("portal:quit", dirty),
  ready: (success) => ipcRenderer.invoke("portal:ready", success),
  onHelp: (handler) => ipcRenderer.on("portal:help", () => handler()),
  onClosing: (handler) => ipcRenderer.on("portal:closing", () => handler()),
  onQuit: (handler) => ipcRenderer.on("portal:request-quit", () => handler()),
});
